mapper.update:
update telegram_channel set name = #{name}, updated_at = NOW()
where chat_id = #{chatId} and name != #{name}
  and not exists (select 1 from robot_telegram_channel where channel_id = telegram_channel.id)

update robot_telegram_channel r
inner join telegram_channel c on c.id = r.channel_id
set r.notice_enabled = #{noticeEnabled,jdbcType=INTEGER}, r.updated_at = NOW()
where r.channel_id = #{channelId,jdbcType=INTEGER}
  and r.typename = #{typename,jdbcType=VARCHAR}
  and r.enabled = 1 and c.enabled = 1
